function throttle(fn, limit) {
  let last = 0;
  let timerId = null;
  let lastArgs = null;

  return function (...args) {
    const now = Date.now();
    const remaining = limit - (now - last);
    lastArgs = args;
    if (remaining <= 0) {
      clearTimeout(timerId);
      timerId = null;
      last = now;
      fn.apply(this, args);
    } else if (!timerId) {
      timerId = setTimeout(() => {
        last = Date.now();
        timerId = null;
        fn.apply(this, lastArgs);
      }, remaining);
    }
  };
}

function memoize(fn) {
  const cache = new Map();
  const wrapped = (arg) => {
    if (cache.has(arg)) return cache.get(arg);
    const value = fn(arg);
    cache.set(arg, value);
    return value;
  };
  wrapped.cache = cache;
  return wrapped;
}

