class PubSub {
  #topics = new Map();

  subscribe(topic, handler) {
    if (!this.#topics.has(topic)) this.#topics.set(topic, new Set());
    this.#topics.get(topic).add(handler);
    return () => this.#topics.get(topic)?.delete(handler);
  }

  publish(topic, data) {
    for (const handler of this.#topics.get(topic) || []) {
      handler(data);
    }
  }
}

