function createValidator(schema) {
  const target = {};
  return new Proxy(target, {
    set(obj, key, value) {
      const expected = schema[key];
      if (!expected) throw new Error(`unknown field: ${String(key)}`);
      if (typeof value !== expected) {
        throw new TypeError(`field ${String(key)} must be ${expected}`);
      }
      obj[key] = value;
      return true;
    },
  });
}

