function createMachine(definition) {
  let current = definition.initial;
  const listeners = new Set();

  return {
    get state() {
      return current;
    },
    onChange(listener) {
      listeners.add(listener);
    },
    send(event) {
      const key = `${current}:${event}`;
      const next = definition.states[current]?.on?.[event];
      if (!next) return current;
      current = next;
      for (const listener of listeners) listener(current, key);
      return current;
    },
  };
}

