function createRepository() {
  const items = [];
  let nextId = 1;

  return {
    add(record) {
      const item = { id: nextId++, ...record };
      items.push(item);
      return item;
    },
    getById(id) {
      return items.find((item) => item.id === id) ?? null;
    },
    getAll() {
      return [...items];
    },
    remove(id) {
      const index = items.findIndex((item) => item.id === id);
      if (index === -1) return false;
      items.splice(index, 1);
      return true;
    },
  };
}

