class QueryBuilder {
  #table;
  #wheres = [];
  #orderBy = null;
  #limit = null;

  constructor(table) {
    this.#table = table;
  }

  where(column, value) {
    this.#wheres.push(`${column} = '${value}'`);
    return this;
  }

  orderBy(column, dir = "ASC") {
    this.#orderBy = `${column} ${dir}`;
    return this;
  }

  limit(n) {
    this.#limit = n;
    return this;
  }

  build() {
    let sql = `SELECT * FROM ${this.#table}`;
    if (this.#wheres.length) sql += ` WHERE ${this.#wheres.join(" AND ")}`;
    if (this.#orderBy) sql += ` ORDER BY ${this.#orderBy}`;
    if (this.#limit != null) sql += ` LIMIT ${this.#limit}`;
    return sql;
  }
}

