  async (ctx, next) => {
    ctx.n += 1;
    log.push("first");
    await next();
  },
  async (ctx, next) => {
    ctx.n += 1;
    log.push("second");
    await next();
  },
]);
console.log(log); // ["first", "second"]

function createTtlCache(ttlMs) {
  const store = new Map();
  return {
    set(key, value) {
      store.set(key, { value, expiresAt: Date.now() + ttlMs });
    },
    get(key) {
      const entry = store.get(key);
      if (!entry) return undefined;
      if (Date.now() > entry.expiresAt) {
        store.delete(key);
        return undefined;
      }
      return entry.value;
    },
    clear() {
      store.clear();
    },
  };
}

